package com.gymflow.app;
import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class ProgressActivity extends AppCompatActivity {
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Progreso del socio");TextView status=Ui.subtitle(this,"Cargando socios...");r.addView(status);Cloud.get(this,"gf_members","select=id,full_name&owner_id=eq."+Session.uid(this)+"&order=full_name.asc",(c,b)->{try{JSONArray a=new JSONArray(b);if(a.length()==0){status.setText("Primero agregá un socio.");return;}String[] names=new String[a.length()];String[] ids=new String[a.length()];for(int i=0;i<a.length();i++){names[i]=a.getJSONObject(i).optString("full_name");ids[i]=a.getJSONObject(i).optString("id");}Spinner member=Ui.spinner(this,names);r.addView(member);EditText weight=Ui.input(this,"Peso actual (kg)");weight.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);r.addView(weight);EditText waist=Ui.input(this,"Cintura (cm)");r.addView(waist);EditText notes=Ui.input(this,"Observaciones");r.addView(notes);Button save=Ui.button(this,"Guardar progreso online");r.addView(save);save.setOnClickListener(v->{try{JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("member_id",ids[member.getSelectedItemPosition()]);if(!weight.getText().toString().isEmpty())o.put("weight_kg",Double.parseDouble(weight.getText().toString()));if(!waist.getText().toString().isEmpty())o.put("waist_cm",Double.parseDouble(waist.getText().toString()));o.put("notes",notes.getText().toString());Cloud.post(this,"gf_progress",o,(cc,bb)->Toast.makeText(this,cc>=200&&cc<300?"Progreso guardado":Cloud.err(bb),Toast.LENGTH_LONG).show());}catch(Exception e){Toast.makeText(this,"Revisá los valores ingresados",Toast.LENGTH_LONG).show();}});status.setText("Seleccioná un socio y registrá su evolución.");}catch(Exception e){status.setText("No se pudieron cargar socios.");}});setContentView(s);}
}
